'use client'; import { useState } from 'react'; import { VendorDataTable } from '@/components/vendor/ui/VendorDataTable';
import { VendorModuleHeader, VendorStatusPill } from '@/components/vendor/ui/VendorModuleHeader';
import { MOCK_SUPPORT } from '@/lib/vendor/mock/data';
import type { SupportTicket } from '@/lib/vendor/types/domain'; const KB = [ { id: 'kb-1', title: 'How to map EDI 850 PO inbound' }, { id: 'kb-2', title: 'GST e-invoice submission checklist' }, { id: 'kb-3', title: 'Escalation matrix · L1–L3' },
]; export function SupportWorkspace() { const [query, setQuery] = useState(''); const filteredKb = KB.filter((k) => k.title.toLowerCase().includes(query.toLowerCase())); return ( <div className="space-y-6"> <VendorModuleHeader title="Support Center" description="Ticket desk, knowledge base, escalation matrix." /> <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search knowledge base…" className="w-full max-w-md rounded-xl border border-vendor-accent/20 px-4 py-2 text-sm bg-vendor-card" /> <ul className="space-y-1 text-sm"> {filteredKb.map((k) => ( <li key={k.id} className="rounded-lg border border-slate-100 px-3 py-2 "> {k.title} </li> ))} </ul> <VendorDataTable<SupportTicket> rows={MOCK_SUPPORT} rowKey={(t) => t.id} columns={[ { key: 'id', header: 'Ticket', render: (t) => t.id }, { key: 'subject', header: 'Subject', render: (t) => t.subject }, { key: 'cat', header: 'Category', render: (t) => t.category }, { key: 'status', header: 'Status', render: (t) => ( <VendorStatusPill label={t.status} tone={t.status === 'Escalated' ? 'danger' : 'info'} /> ), }, ]} /> </div> );
}
